create table public.document_shop_packages (slug text primary key, title text not null, price_cents integer not null check(price_cents>0), filename text not null, payload bytea not null, sha256 text not null check(length(sha256)=64), version text not null, sale_enabled boolean not null default false, uploaded_at timestamptz not null default now()); alter table public.document_shop_packages enable row level security; revoke all on public.document_shop_packages from public,anon,authenticated; grant select,insert,update,delete on public.document_shop_packages to service_role;
